31	/**
32	 * `tagList` 3분기: 키 없음 → undefined(생성 시 [], 수정 시 기존 유지),
33	 * `null`/배열 아님/원소가 빈 문자열 → 422, 배열 → 순서 보존 + 중복 제거.
34	 * 중복 제거는 `ArticleTag`의 복합 PK(articleId, tagId) 위반을 막기 위한 것이다.
35	 */
36	function parseTagList(payload: Record<string, unknown>): string[] | undefined {
37	  if (!Object.hasOwn(payload, 'tagList')) return undefined;
38	
39	  const raw = payload.tagList;
40	  if (!Array.isArray(raw)) throw ApiError.unprocessable({ tagList: ['is invalid'] });
