import { Prisma } from '@prisma/client';
import type { FastifyPluginAsync } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { requireAuth, optionalAuth } from '../auth/hooks.js';
import { toArticleResponse } from '../serializers/index.js';
import { asArticleInclude, findArticleOr404, normalizeArticle } from '../services/article-query.js';
import { makeSlug } from '../services/slug.js';

type SlugParams = { slug: string };

const TEXT_FIELDS = ['title', 'description', 'body'] as const;
type TextField = (typeof TEXT_FIELDS)[number];

/** 바디 스키마를 붙이지 않으므로(fastify-project-conventions) 여기서 직접 판별한다. */
function articlePayload(body: unknown): Record<string, unknown> {
  if (typeof body !== 'object' || body === null) return {};
  const article = (body as Record<string, unknown>).article;
  if (typeof article !== 'object' || article === null) return {};
  return article as Record<string, unknown>;
}

/** 빈 문자열·null·비문자열 모두 422 `can't be blank`. */
function requireText(payload: Record<string, unknown>, field: TextField): string {
  const value = payload[field];
  if (typeof value !== 'string' || value.trim() === '') throw ApiError.blank(field);
  return value;
}

/**
 * `tagList` 3분기: 키 없음 → undefined(생성 시 [], 수정 시 기존 유지),
 * `null`/배열 아님/원소가 빈 문자열 → 422, 배열 → 순서 보존 + 중복 제거.
 * 중복 제거는 `ArticleTag`의 복합 PK(articleId, tagId) 위반을 막기 위한 것이다.
 */
function parseTagList(payload: Record<string, unknown>): string[] | undefined {
  if (!Object.hasOwn(payload, 'tagList')) return undefined;

  const raw = payload.tagList;
  if (!Array.isArray(raw)) throw ApiError.unprocessable({ tagList: ['is invalid'] });

  const tags: string[] = [];
  for (const item of raw) {
    if (typeof item !== 'string' || item.trim() === '') {
      throw ApiError.unprocessable({ tagList: ['is invalid'] });
    }
    if (!tags.includes(item)) tags.push(item);
  }
  return tags;
}

/** 입력 순서를 `order` 컬럼에 그대로 저장한다. Tag는 없으면 만든다. */
function tagCreateInput(tags: string[]): Prisma.ArticleTagCreateWithoutArticleInput[] {
  return tags.map((name, order) => ({
    order,
    tag: { connectOrCreate: { where: { name }, create: { name } } },
  }));
}

function isSlugConflict(error: unknown): boolean {
  return error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002';
}

/**
 * 존재(404) → 소유권(403) 순서. 쓰기 전에 호출해 부분 쓰기를 원천 차단한다.
 * findArticleOr404는 응답 조립용이라 authorId를 담지 않으므로 별도 조회를 쓴다.
 */
async function findOwnArticleOr40x(slug: string, userId: number) {
  const article = await prisma.article.findUnique({
    where: { slug },
    select: { id: true, authorId: true },
  });
  if (article === null) throw ApiError.notFound('article');
  if (article.authorId !== userId) throw ApiError.forbidden('article');
  return article;
}

export const articlesRoutes: FastifyPluginAsync = async (app) => {
  // 태스크 09: GET /articles (목록)
  // 태스크 10: GET /articles/feed — 반드시 아래 /articles/:slug보다 위에 둘 것.

  app.post('/articles', { preHandler: requireAuth }, async (req, reply) => {
    const payload = articlePayload(req.body);
    const title = requireText(payload, 'title');
    const description = requireText(payload, 'description');
    const body = requireText(payload, 'body');
    const tags = parseTagList(payload) ?? [];
    const authorId = req.userId!;

    // 랜덤 접미사가 충돌하면 slug만 새로 뽑아 재시도한다.
    for (let attempt = 0; ; attempt++) {
      try {
        const created = await prisma.article.create({
          data: {
            slug: makeSlug(title),
            title,
            description,
            body,
            authorId,
            tags: { create: tagCreateInput(tags) },
          },
          include: asArticleInclude(authorId),
        });
        return reply.code(201).send(toArticleResponse(normalizeArticle(created)));
      } catch (error) {
        if (attempt >= 4 || !isSlugConflict(error)) throw error;
      }
    }
  });

  app.get<{ Params: SlugParams }>(
    '/articles/:slug',
    // 문서는 "no auth"라고 하지만 favorites.hurl이 인증 헤더를 붙여 favorited: true를 기대한다.
    { preHandler: optionalAuth },
    async (req) => toArticleResponse(await findArticleOr404(req.params.slug, req.userId)),
  );

  app.put<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req) => {
      const userId = req.userId!;
      const existing = await findOwnArticleOr40x(req.params.slug, userId);

      const payload = articlePayload(req.body);
      // slug는 title이 바뀌어도 유지한다.
      const data: Prisma.ArticleUpdateInput = {};
      for (const field of TEXT_FIELDS) {
        if (Object.hasOwn(payload, field)) data[field] = requireText(payload, field);
      }
      const tags = parseTagList(payload);

      // @updatedAt은 스칼라가 실제로 바뀔 때만 갱신되므로 명시적으로 넣는다.
      data.updatedAt = new Date();

      await prisma.$transaction(async (tx) => {
        // tagList 키가 없으면 기존 태그 유지, []면 전체 삭제, 배열이면 순서 그대로 교체.
        if (tags !== undefined) {
          await tx.articleTag.deleteMany({ where: { articleId: existing.id } });
          data.tags = { create: tagCreateInput(tags) };
        }
        await tx.article.update({ where: { id: existing.id }, data });
      });

      return toArticleResponse(await findArticleOr404(req.params.slug, userId));
    },
  );

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req, reply) => {
      const existing = await findOwnArticleOr40x(req.params.slug, req.userId!);
      await prisma.article.delete({ where: { id: existing.id } });
      return reply.code(204).send();
    },
  );
};

